"g|eo|A1|Kesesuaian dengan Kata Ganti":[["Ni estas amikoj.","","Kami adalah teman.","estas amikoj","adalah teman"],["Ili estas junaj.","","Mereka muda.","estas junaj","muda"],["Li estas alta kaj forta.","","Dia tinggi dan kuat.","estas alta","tinggi"],["Ni estas bonaj kaj feliĉaj.","","Kami baik dan bahagia.","estas bonaj","baik"],["Vi estas bonaj lernantoj.","","Kalian murid yang baik.","estas bonaj lernantoj","murid yang baik"],["Ŝi estas bela kaj juna.","","Dia cantik dan muda.","estas bela","cantik"],["Ni estas malgrandaj, sed ili estas grandaj.","","Kami kecil, tetapi mereka besar.","estas grandaj","besar"],["Ili estas instruistoj kaj ni estas lernantoj.","","Mereka guru dan kami murid.","estas lernantoj","murid"],["Ni estas hejme kaj la infanoj estas en la lernejo.","","Kami ada di rumah dan anak-anak ada di sekolah.","Ni estas hejme","Kami ada di rumah"],["Mi estas laca, sed ili estas feliĉaj hodiaŭ.","","Saya lelah, tetapi mereka bahagia hari ini.","estas feliĉaj","bahagia"],["Vi estas ankoraŭ junaj, sed ni estas maljunaj.","","Kalian masih muda, tetapi kami sudah tua.","estas maljunaj","tua"],["Ĝi estas bela birdo kaj ĝi estas feliĉa.","","Itu burung yang indah dan dia bahagia.","Ĝi estas bela birdo","Itu burung yang indah"]],
"g|eo|A1|Konjugasi Kala Kini":[["Mi lernas Esperanton.","","Saya belajar Esperanto.","Mi lernas","Saya belajar"],["Vi parolas rapide.","","Kamu berbicara dengan cepat.","Vi parolas","Kamu berbicara"],["Li kuiras supon.","","Dia memasak sup.","Li kuiras","Dia memasak"],["Ŝi aŭskultas muzikon.","","Dia mendengarkan musik.","Ŝi aŭskultas","Dia mendengarkan"],["Ĝi manĝas fiŝon.","","Dia makan ikan.","Ĝi manĝas","Dia makan"],["Ni vojaĝas per trajno.","","Kami bepergian naik kereta.","Ni vojaĝas","Kami bepergian"],["Ili laboras en banko.","","Mereka bekerja di bank.","Ili laboras","Mereka bekerja"],["Ni dormas malfrue.","","Kami tidur larut.","Ni dormas","Kami tidur"],["Ili ludas futbalon ĉiusabate.","","Mereka bermain sepak bola setiap hari Sabtu.","Ili ludas","Mereka bermain"],["Mi estas hejme kaj vi estas en la lernejo.","","Saya di rumah dan kamu di sekolah.","Mi estas","Saya"],["Li havas novan aŭton kaj ŝi havas malnovan biciklon.","","Dia punya mobil baru dan dia punya sepeda tua.","Li havas","Dia punya"],["Mi ofte aŭdas birdojn matene.","","Saya sering mendengar burung pada pagi hari.","Mi ofte aŭdas","Saya sering mendengar"]],
"g|eo|A1|Kala Lampau -is":[["Mi manĝis.","","Saya sudah makan.","manĝis","sudah makan"],["La birdo flugis.","","Burung itu terbang (tadi).","flugis","terbang"],["Ŝi dormis bone.","","Dia tidur nyenyak.","dormis","tidur"],["Li laboris en la ĝardeno.","","Dia bekerja di kebun.","laboris","bekerja"],["Ni ludis ekstere hieraŭ.","","Kemarin kami bermain di luar.","ludis","bermain"],["La infanoj kuris al la lernejo.","","Anak-anak berlari ke sekolah.","kuris","berlari"],["Hieraŭ mi legis libron.","","Kemarin saya membaca buku.","legis","membaca"],["Mi vidis belan birdon sur la arbo.","","Saya melihat burung indah di pohon.","vidis","melihat"],["Mia patrino kuiris bonan manĝon.","","Ibu saya memasak makanan yang enak.","kuiris","memasak"],["Ili iris al la urbo kaj aĉetis panon.","","Mereka pergi ke kota dan membeli roti.","aĉetis","membeli"],["Hieraŭ la suno brilis, sed hodiaŭ pluvas.","","Kemarin matahari bersinar, tetapi hari ini hujan.","brilis","bersinar"],["La hundo kuris en la ĝardeno kaj la kato dormis sur la tablo.","","Anjing berlari di kebun dan kucing tidur di atas meja.","dormis","tidur"]],
"g|eo|A1|Preposisi (Kata Depan)":[["La arbo estas en la ĝardeno.","","Pohon itu ada di kebun.","en la ĝardeno","di kebun"],["La libro estas sur la tablo.","","Buku itu ada di atas meja.","sur la tablo","di atas meja"],["La kato dormas sub la tablo.","","Kucing tidur di bawah meja.","sub la tablo","di bawah meja"],["Mi iras al la lernejo.","","Saya pergi ke sekolah.","al la lernejo","ke sekolah"],["Ŝi venas de la urbo.","","Dia datang dari kota.","de la urbo","dari kota"],["La infanoj ludas kun la hundo.","","Anak-anak bermain dengan anjing itu.","kun la hundo","dengan anjing itu"],["Mi parolas kun la instruisto.","","Saya berbicara dengan guru.","kun la instruisto","dengan guru"],["La domo estas apud la lernejo.","","Rumah itu ada di sebelah sekolah.","apud la lernejo","di sebelah sekolah"],["La butiko estas antaŭ la domo.","","Toko itu ada di depan rumah.","antaŭ la domo","di depan rumah"],["La ĝardeno estas malantaŭ la domo.","","Kebun itu ada di belakang rumah.","malantaŭ la domo","di belakang rumah"],["Mi aĉetas panon por mia patrino.","","Saya membeli roti untuk ibu saya.","por mia patrino","untuk ibu saya"],["Ŝi sidas inter Anna kaj Petro.","","Dia duduk di antara Anna dan Petro.","inter Anna kaj Petro","di antara Anna dan Petro"],["Mi laboras ĝis la vespero.","","Saya bekerja sampai sore.","ĝis la vespero","sampai sore"],["La infanoj iras per buso al la urbo.","","Anak-anak pergi ke kota naik bus.","per buso","naik bus"]],
"g|eo|A1|Akusatif Kata Ganti":[["Li aŭdas min.","","Dia mendengar saya.","aŭdas min","mendengar saya"],["Mi helpas vin hodiaŭ.","","Saya membantu kamu hari ini.","helpas vin","membantu kamu"],["Ŝi amas lin.","","Dia mencintai pria itu.","amas lin","pria itu"],["Li vidas ŝin en la ĝardeno.","","Dia melihat wanita itu di kebun.","vidas ŝin","wanita itu"],["Ŝi vizitas nin ĉiusabate.","","Dia mengunjungi kami setiap hari Sabtu.","vizitas nin","mengunjungi kami"],["Ili vidas nin en la parko.","","Mereka melihat kami di taman.","vidas nin","melihat kami"],["La instruisto helpas ilin.","","Guru membantu mereka.","helpas ilin","membantu mereka"],["La viro vidis vin kaj min.","","Pria itu melihat kamu dan aku.","vin kaj min","kamu dan aku"],["Mi vidas ilin ĉiutage en la lernejo.","","Saya melihat mereka setiap hari di sekolah.","vidas ilin","melihat mereka"],["La pano estas bona kaj mi manĝas ĝin.","","Rotinya enak dan saya memakannya.","manĝas ĝin","memakannya"],["Ili invitas nin al la festo.","","Mereka mengundang kami ke pesta.","invitas nin","mengundang kami"],["Mia patrino vokas min kaj mi helpas ŝin.","","Ibu saya memanggil saya dan saya membantunya.","vokas min","memanggil saya"],["Mi ne vidas vin, ĉar la ĉambro estas malluma.","","Saya tidak melihat kamu, karena kamarnya gelap.","ne vidas vin","tidak melihat kamu"]],
