"g|eo|A1|Kata Kerja Refleksif":[["Mi vestas min.","","Saya berpakaian.","vestas min","berpakaian"],["Ŝi banas sin vespere.","","Dia mandi pada malam hari.","banas sin","mandi"],["Li razas sin ĉiumatene.","","Dia bercukur setiap pagi.","razas sin","bercukur"],["Mi sentas min bone hodiaŭ.","","Saya merasa sehat hari ini.","sentas min","merasa"],["Vi sentas vin malbone?","","Kamu merasa tidak enak badan?","sentas vin","merasa"],["Mi lavas min kaj poste manĝas.","","Saya mandi dan setelah itu makan.","lavas min","mandi"],["La infanoj vestas sin rapide.","","Anak-anak berpakaian dengan cepat.","vestas sin","berpakaian"],["Ni preparas nin por la vojaĝo.","","Kami bersiap untuk perjalanan.","preparas nin","bersiap"],["Ŝi kombas sin antaŭ la spegulo.","","Dia menyisir rambut di depan cermin.","kombas sin","menyisir rambut"],["Mi sekigas min per tuko.","","Saya mengeringkan badan dengan handuk.","sekigas min","mengeringkan badan"],["Ni vestas nin varme, ĉar estas malvarme.","","Kami berpakaian hangat karena dingin.","vestas nin","berpakaian"],["Ŝi sentas sin sola en la nova urbo.","","Dia merasa sendirian di kota baru.","sentas sin","merasa"],["Vi bone kaŝis vin, mi ne vidis vin.","","Kamu bersembunyi dengan baik, aku tidak melihatmu.","kaŝis vin","bersembunyi"]],
