"g|eo|A1|Kata Sifat Posesif":[["Mia patro estas hejme.","","Ayah saya ada di rumah.","Mia patro","Ayah saya"],["Ĉi tiu estas via libro.","","Ini buku kamu.","via libro","buku kamu"],["Ŝia kato estas tre bela.","","Kucingnya sangat cantik.","Ŝia kato","Kucingnya"],["Nia lernejo estas granda.","","Sekolah kami besar.","Nia lernejo","Sekolah kami"],["Lia fratino estas instruistino.","","Saudarinya adalah guru.","Lia fratino","Saudarinya"],["Mia kafo estas tro varma.","","Kopi saya terlalu panas.","Mia kafo","Kopi saya"],["Kie estas via telefono?","","Di mana teleponmu?","via telefono","teleponmu"],["Ilia domo havas ruĝan pordon.","","Rumah mereka punya pintu merah.","Ilia domo","Rumah mereka"],["Ŝia patrino laboras en hospitalo.","","Ibunya bekerja di rumah sakit.","Ŝia patrino","Ibunya"],["Miaj gepatroj loĝas en Berlino.","","Orang tua saya tinggal di Berlin.","Miaj gepatroj","Orang tua saya"],["Viaj infanoj estas tre bonaj.","","Anak-anakmu sangat baik.","Viaj infanoj","Anak-anakmu"],["Liaj libroj estas sur la tablo.","","Buku-bukunya ada di atas meja.","Liaj libroj","Buku-bukunya"],["La kato dormas, kaj ĝia lito estas mola.","","Kucing itu tidur, dan tempat tidurnya empuk.","ĝia lito","tempat tidurnya"],["Ilia aŭto estas nova, sed nia aŭto estas malnova.","","Mobil mereka baru, tetapi mobil kami tua.","Ilia aŭto","Mobil mereka"]],
